 public function build(array $ctx):array{$eval=$ctx['policy_evaluation']??null;$scope=$eval['selection_scope']??null;$codes=[];$warnings=[];$blockers=[];if(!is_array($eval)||($eval['status']??null)!=='eligible_for_reference_selection')return $this->empty('SELECTED_PROPOSAL_UNAVAILABLE');$isEntry=$scope==='entry_candidate_reference';$candidate=$ctx['action_candidate']??[];$plan=$ctx['action_plan']??[];$approval=$isEntry?($ctx['portfolio_approval']??[]):($ctx['management_portfolio_approval']??[]);$type=$isEntry?'long_entry':($plan['proposed_management_action']??null);$qty=$isEntry?($ctx['reference_quantity']??($ctx['trade_plan']['execution_readiness']['reference_quantity']??null)):($plan['quantity_plan']['proposed_quantity_reference']??null);$remaining=$isEntry?null:($plan['quantity_plan']['remaining_quantity_reference']??null);$payload=['schema'=>$this->config['selected_proposal_schema_version'],'scope'=>$scope,'decision_at'=>$ctx['decision_at']??null,'candidate_id'=>$candidate['candidate_id']??null,'ticker'=>$candidate['ticker']??($ctx['ticker']??null),'portfolio_id'=>$eval['portfolio_id']??($approval['portfolio_id']??null),'position_id'=>$plan['position_id']??null,'management_candidate_id'=>$eval['management_candidate_id']??null,'action_plan_id'=>$eval['action_plan_id']??null,'proposal_type'=>$type,'reference_quantity'=>$qty,'remaining_quantity'=>$remaining,'approval_schema'=>$approval['schema_version']??null,'approval_status'=>$approval['status']??null,'approval_id'=>$approval['approval_id']??($approval['metadata']['approval_context_fingerprint']??null),'policy_id'=>$eval['policy_id']??null,'policy_version'=>$eval['policy_version']??null,'policy_status'=>$eval['status']??null];$id=hash('sha256',json_encode($payload,JSON_UNESCAPED_SLASHES|JSON_PRESERVE_ZERO_FRACTION));foreach(['SELECTED_PROPOSAL_REFERENCE_SELECTED','SELECTED_PROPOSAL_REFERENCE_ONLY','SELECTED_PROPOSAL_PRODUCTION_NOT_SELECTED','SELECTED_PROPOSAL_EXECUTION_NOT_SELECTED','SELECTED_PROPOSAL_NON_EXECUTA