 return ['schema_version'=>$this->config['selected_proposal_schema_version'],'status'=>'selected_reference','selected_proposal_id'=>$id,'selection_scope'=>$scope,'proposal_type'=>$type,'source_identity'=>['candidate_id'=>$candidate['candidate_id']??null,'position_id'=>$plan['position_id']??null,'management_candidate_id'=>$eval['management_candidate_id']??null,'action_plan_id'=>$eval['action_plan_id']??null],'proposal'=>['intent'=>$isEntry?'long_entry':null,'proposed_action'=>$isEntry?null:$type,'reference_quantity'=>$qty,'remaining_quantity_reference'=>$remaining],'approval_binding'=>['reference_approval_schema'=>$approval['schema_version']??null,'reference_approval_status'=>$approval['status']??null,'reference_approval_id'=>$payload['approval_id']],'selection_binding'=>['policy_id'=>$eval['policy_id']??null,'policy_version'=>$eval['policy_version']??null,'policy_evaluation_status'=>$eval['status']??null],'selection_result'=>['reference_selected'=>true,'production_selected'=>false,'execution_selected'=>false],'production_approval'=>['status'=>'not_implemented','selected_proposal_id'=>$id,'approved'=>false],'execution_authorization'=>['status'=>'not_implemented','selected_proposal_id'=>$id,'authorized'=>false],'promotion'=>['status'=>'not_implemented','selected_proposal_id'=>$id,'promoted_action'=>null,'executable_action'=>null],'execution'=>['executable'=>false,'instruction'=>null],'reason_codes'=>$this->ordered($codes),'warnings'=>$warnings,'blockers'=>$this->ordered($blockers),'metadata'=>['identity_payload'=>$payload]];}
 public function empty($code='SELECTED_PROPOSAL_UNAVAILABLE'):array{return ['schema_version'=>$this->config['selected_proposal_schema_version'],'status'=>'unavailable','selected_proposal_id'=>null,'selection_scope'=>null,'proposal_type'=>null,'source_identity'=>['candidate_id'=>null,'position_id'=>null,'management_candidate_id'=>null,'action_plan_id'=>null],'proposal'=>['intent'=>null,'proposed_action'=>null,'reference_quantity'=>null,'remaining_quantity_reference'=>null],'approval_binding'=>['reference_approval_schema'=>null,'reference_approval_status'=>null,'reference_approval_id'=>null],'selection_binding'=>['policy_id'=>null,'policy_version'=>null,'policy_evaluation_status'=>null],'selection_result'=>['reference_selected'=>false,'production_selected'=>false,'execution_selected'=>false],'production_approval'=>['status'=>'not_implemented','selected_proposal_id'=>null,'approved'=>false],'execution_authorization'=>['status'=>'not_implemented','selected_proposal_id'=>null,'authorized'=>false],'promotion'=>['status'=>'not_implemented','selected_proposal_id'=>null,'promoted_action'=>null,'executable_action'=>null],'execution'=>['executable'=>false,'instruction'=>null],'reason_codes'=>[$code],'warnings'=>[],'blockers'=>[$code],'metadata'=>[]];}
 protected function add(&$c,$code,&$target=null){if(!in_array($code,$c,true))$c[]=$code;if(is_array($target)&&!in_array($code,$target,true))$target[]=$code;}protected function ordered($c){sort($c);return array_values(array_unique($c));}}
